  for(const [k,t] of Object.entries({name_ko:"TEXT NOT NULL DEFAULT ''",specification:"TEXT NOT NULL DEFAULT ''",dimensions:"TEXT NOT NULL DEFAULT ''",units_json:"TEXT NOT NULL DEFAULT '[]'",image_file:"TEXT NOT NULL DEFAULT ''",revision:'INTEGER NOT NULL DEFAULT 1'}))add('pink_salt_packaging_items',k,t);
